43	impl DirHandle {
44	    fn offset(&self) -> i64 {
45	        self.offset.load(Ordering::SeqCst)
46	    }
47	
48	    fn next_offset(&self) {
49	        self.offset.fetch_add(1, Ordering::SeqCst);
50	    }
