28	#[tokio::test]
29	async fn test_read_dir_root(prefix: &str) {
30	    let prefix = Prefix::new(prefix).expect("valid prefix");
31	    let (client, fs) = make_test_filesystem("test_read_dir", &prefix, Default::default());
32	
33	    client.add_object(
34	        &format!("{prefix}file1.txt"),
35	        MockObject::constant(0xa1, 15, ETag::from_str("test_etag_1").unwrap()),
36	    );
37	    client.add_object(
38	        &format!("{prefix}file2.txt"),
39	        MockObject::constant(0xa2, 15, ETag::from_str("test_etag_2").unwrap()),
40	    );
41	    client.add_object(
42	        &format!("{prefix}file3.txt"),
43	        MockObject::constant(0xa3, 15, ETag::from_str("test_etag_3").unwrap()),
44	    );
45	
46	    let uid = getuid().into();
47	    let gid = getgid().into();
48	    let dir_perm: u16 = 0o755;
49	    let file_perm: u16 = 0o644;
50	
51	    // Listing the root directory doesn't require resolving it first, can just opendir the root inode
52	    let dir_handle = fs.opendir(FUSE_ROOT_INODE, 0).await.unwrap().fh;
53	    let mut reply = Default::default();
54	    let _reply = fs.readdirplus(1, dir_handle, 0, &mut reply).await.unwrap();
55	
56	    assert_eq!(reply.entries.len(), 2 + 3);
57	
58	    // TODO `stat` on these needs to work
59	    assert_eq!(reply.entries[0].name, ".");
60	    assert_eq!(reply.entries[0].ino, FUSE_ROOT_INODE);
61	    assert_attr(reply.entries[0].attr, FileType::Directory, 0, uid, gid, dir_perm);
62	    assert_eq!(reply.entries[1].name, "..");
63	    assert_eq!(reply.entries[1].ino, FUSE_ROOT_INODE);
64	    assert_attr(reply.entries[1].attr, FileType::Directory, 0, uid, gid, dir_perm);
65	
66	    let mut offset = reply.entries[0].offset.max(reply.entries[1].offset);
67	    for (i, reply) in reply.entries.iter().skip(2).enumerate() {
68	        let expected: OsString = format!("file{}.txt", i + 1).into();
69	        assert_eq!(reply.name, expected);
70	        assert_eq!(reply.attr.kind, FileType::RegularFile);
71	        assert!(reply.ino > 1);
72	
73	        let attr = fs.getattr(reply.ino).await.unwrap();
74	        assert_eq!(attr.attr.ino, reply.ino);
75	        assert_attr(attr.attr, FileType::RegularFile, 15, uid, gid, file_perm);
76	
77	        let fh = fs.open(reply.ino, 0x8000, 0).await.unwrap().fh;
78	        let bytes_read = fs
79	            .read(reply.ino, fh, 0, 4096, 0, None)
80	            .await
81	            .expect("fs read should succeed");
82	        assert_eq!(&bytes_read[..], &[0xa0 + (i as u8 + 1); 15]);
83	        fs.release(reply.ino, fh, 0, None, true).await.unwrap();
84	
85	        offset = offset.max(reply.offset);
86	    }
87	
88	    assert!(offset > 0);
89	
90	    let mut reply = Default::default();
91	    let _reply = fs
92	        .readdir(FUSE_ROOT_INODE, dir_handle, offset, &mut reply)
93	        .await
94	        .unwrap();
95	    assert_eq!(reply.entries.len(), 0);
96	
97	    fs.releasedir(FUSE_ROOT_INODE, dir_handle, 0).await.unwrap();
98	}
