            FileHandleState::Read { request: _, pid } => f.debug_struct("Read").field("pid", pid).finish(),
            FileHandleState::Write(arg0) => f.debug_tuple("Write").field(arg0).finish(),
            FileHandleState::Closed => f.debug_struct("Closed").finish(),
        }
    }
}

