+    let mut rng = ChaCha20Rng::seed_from_u64(0x12345678 + object_size as u64);
+    let mut expected = vec![0; object_size];
+    rng.fill(&mut expected[..]);
+    client.add_object("file", MockObject::from_bytes(&expected[..], ETag::for_tests()));
