+    let ino = reply.entries[2].ino;
+
+    let fh = fs.open(ino, 0x8000, 0).await.unwrap().fh;
+
+    let mut rng = ChaCha20Rng::seed_from_u64(0x12345678);
+    for _ in 0..10 {
+        let offset = rng.gen_range(0..object_size);
