+    assert_eq!(reply.entries[1].name, "..");
+    assert_eq!(reply.entries[1].ino, FUSE_ROOT_INODE);
+    assert_attr(reply.entries[1].attr, FileType::Directory, 0, uid, gid, dir_perm);
