+    let new_entries = ls(&fs, dir_handle, 0, 20).await;
+    assert_eq!(new_entries.len(), 3); // 1 new local file + 2 dirs (. and ..) = 3 entries
+}
+
+#[cfg(feature = "s3_tests")]
