+                .await
+                .unwrap();
+            superblock
+                .write(&client, new_inode.inode.ino(), FUSE_ROOT_INODE, 0, false, false)
+                .await;
+        }
+
+        // Create some local directories
+        for dirname in ["dir2", "dm2", "file2"] {
+            let _new_inode = superblock
+                .create(
+                    &client,
+                    FUSE_ROOT_INODE,
+                    OsStr::from_bytes(dirname.as_bytes()),
+                    InodeKind::Directory,
+                )
+                .await
+                .unwrap();
